    'RegisterSimpleRisk'=>'Зареєструвати SimpleRisk',
    'RegistrationText'=>'Зареєстрованим примірникам SimpleRisk негайно надається доступ до додаткових функцій Upgrade and Secure Controls Framework (SCF). Upgrade Extra надає можливість створювати резервні копії та оновлювати ваш екземпляр SimpleRisk одним натисканням кнопки. Secure Controls Framework (SCF) Extra надає загальну структуру контролю, яка інтегрована у функціональність SimpleRisk Governance. Після реєстрації SimpleRisk ваша реєстраційна інформація буде надіслана на сервер SimpleRisk. Надана реєстраційна інформація буде використовуватися SimpleRisk для сповіщення клієнтів про нові випуски та оновлення безпеки. Реєстрація SimpleRisk дозволить вам отримати доступ до наших маркетингових повідомлень, але ви можете відмовитися в будь-який час за посиланням для скасування підписки в цих повідомленнях. SimpleRisk поважає конфіденційність наших клієнтів, і інформація, надана нам у процесі реєстрації SimpleRisk, ніколи не буде продана третім особам.',
